package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object FoundationsCards {
    private val T = Track.FOUNDATIONS
    val cards: List<Card> = listOf(
        // ---- Level 1 · Rookie (adds to the 11 starter cards) ------------------------------------
        quiz("fb-needs-wants", T, 1, "Which of these is a need rather than a want?",
            listOf("Rent and basic food", "A new phone when yours still works", "Weekend nyama choma with friends", "A bigger data bundle for TikTok"), 0,
            "Needs keep you housed, fed, healthy and able to earn. Wants make life nicer. Both belong in a budget, but needs get paid first."),
        concept("fb-track-first", T, 1, "Why track your spending for a month before you set a budget?",
            "Memory forgets the small stuff: matatu fares, airtime, snacks, Fuliza fees. Your M-Pesa statement shows what really happened, so your budget starts from the truth, not a guess.",
            tryThis = "See last month's spending by category in Patterns.", action = Action.PATTERNS),
        concept("fb-gross-net", T, 1, "Your payslip says Ksh 50,000 but less lands in M-Pesa. Which number do you budget with?",
            "Net pay: what's left after PAYE, NSSF, SHIF, the housing levy and any loan deductions. Gross pay is a number you never get to spend.",
            source = "KRA", tryThis = "Check this month's payslip and note your real take-home.", timeSensitive = true),

        // ---- Level 2 · Hustler ----------------------------------------------------------------
        quiz("fb-zero-based", T, 2, "In a zero-based budget, income minus everything you plan (spending, saving, debt) should equal…",
            listOf("Zero", "10% of income", "Whatever is left at month end", "Your rent"), 0,
            "Every shilling gets a job, including savings and fun. \"Zero\" doesn't mean spend it all: it means nothing is left unplanned.",
            source = "Common budgeting method", tryThis = "Give every Ksh of this month's income an envelope.", action = Action.BUDGETS),
        quiz("fb-503020-calc", T, 2, "Take-home is Ksh 60,000. Under 50/30/20, how much goes to saving and paying off debt?",
            listOf("Ksh 12,000", "Ksh 18,000", "Ksh 30,000", "Ksh 6,000"), 0,
            "20% of 60,000 = 12,000. Needs get up to 30,000 and wants 18,000. If rent alone is half your pay, shrink wants first, not savings.",
            source = "Warren & Tyagi, 2005"),
        concept("fb-sinking-fund", T, 2, "What is a sinking fund?",
            "Money you set aside bit by bit for a cost you know is coming: school fees, a rent deposit, Christmas travel to shags. Ksh 36,000 of January fees is Ksh 3,000 a month, not a January panic.",
            tryThis = "Create an envelope for your next big known cost.", action = Action.BUDGETS),
        quiz("fb-sinking-calc", T, 2, "You need Ksh 24,000 for a new-house deposit in 8 months. How much a month?",
            listOf("Ksh 3,000", "Ksh 2,400", "Ksh 4,000", "Ksh 8,000"), 0,
            "24,000 ÷ 8 = 3,000. Start now and it's a normal bill; start in month 6 and you need 8,000 a month."),
        concept("fb-irregular-income", T, 2, "Your hustle pays differently every month. How do you budget?",
            "Budget on your low month, not your average. Park all income in one holding pot, pay yourself a fixed \"salary\" from it, and let good months top up a buffer for the bad ones.",
            tryThis = "Look back 6 months and find your lowest income month.", action = Action.PATTERNS, signals = setOf(Signal.MONEY_IN_RECENT)),
        quiz("fb-irregular-base", T, 2, "Last 6 months: Ksh 18k, 35k, 22k, 40k, 15k, 30k. Safest amount to build your basic budget on?",
            listOf("About Ksh 15,000 (your low month)", "About Ksh 26,700 (the average)", "Ksh 40,000 (your best month)", "Ksh 35,000 (a good month)"), 0,
            "If your needs fit inside the low month, a bad month is just a bad month, not a crisis. Anything above it feeds the buffer, savings and wants."),
        quiz("fb-withdraw-once", T, 2, "Withdrawing Ksh 500 four times vs Ksh 2,000 once at an agent. Fee difference?",
            listOf("About Ksh 87 more for four trips", "The same", "About Ksh 10 more", "Four trips are cheaper"), 0,
            "Ksh 101–2,500 withdrawals each cost Ksh 29 on current tariffs. Four trips: Ksh 116. One trip: Ksh 29. Fewer, planned withdrawals win.",
            source = "Safaricom tariffs, 2026", signals = setOf(Signal.HIGH_FEES), timeSensitive = true),
        quiz("fb-send-free", T, 2, "What does it cost to send Ksh 100 or less to another M-Pesa user?",
            listOf("Free", "Ksh 7", "Ksh 13", "Ksh 1 per shilling"), 0,
            "Transfers of Ksh 1–100 are free. From Ksh 101 the fee starts (about Ksh 7 up to Ksh 500), then rises by band. Tiny sends to family are fee-free.",
            source = "Safaricom tariffs, 2026", timeSensitive = true),
        quiz("fb-till-not-send", T, 2, "You pay a fundi Ksh 1,200. Which way costs you, the payer, nothing?",
            listOf("His Buy Goods till", "Send Money to his number", "Withdraw cash and pay him", "Paybill to his bank"), 0,
            "Till payments are free for the customer. Send Money of Ksh 1,001–1,500 costs about Ksh 23, and withdrawing costs Ksh 29. Ask \"una till?\"",
            source = "Safaricom tariffs, 2026", signals = setOf(Signal.HIGH_FEES), timeSensitive = true),
        quiz("fb-small-leaks", T, 2, "Ksh 150 a day on snacks and small bundles adds up to about how much a year?",
            listOf("About Ksh 55,000", "About Ksh 15,000", "About Ksh 4,500", "About Ksh 150,000"), 0,
            "150 × 365 = 54,750. Small daily spends are invisible one by one and huge as a year. You don't have to stop; just decide on purpose.",
            tryThis = "Find your most frequent small spend in Patterns.", action = Action.PATTERNS),
        concept("fb-fixed-variable", T, 2, "Why is cutting a fixed cost often better than cutting a variable one?",
            "A fixed cost (rent, subscriptions, a loan instalment) repeats every month, so one decision saves you every month. Cutting a variable cost (eating out) needs willpower again and again."),
        concept("fb-annual-costs", T, 2, "Your budget works for 3 months, then something \"unexpected\" breaks it. What's missing?",
            "The yearly costs: insurance, school fees, car service, birthdays, December. They're not unexpected, just irregular. Add them up for the year, divide by 12, and save that monthly.",
            signals = setOf(Signal.OVER_BUDGET)),
        quiz("fb-chama-math", T, 2, "In a merry-go-round chama, who effectively gets an interest-free loan?",
            listOf("Members who receive the pot early", "Members who receive it last", "Everyone equally", "Only the treasurer"), 0,
            "Early receivers get the whole pot now and repay through contributions. Late receivers lend to the group at 0% while inflation eats the value. Rotations trade this off fairly."),

        // ---- Level 3 · Pro --------------------------------------------------------------------
        quiz("fb-compound-lump", T, 3, "Ksh 100,000 earns 10% a year, compounded yearly. After 3 years you have…",
            listOf("Ksh 133,100", "Ksh 130,000", "Ksh 110,000", "Ksh 300,000"), 0,
            "Year 1: 110,000. Year 2: 121,000. Year 3: 133,100. The extra 3,100 over simple interest is interest earning interest."),
        quiz("fb-simple-compound", T, 3, "Ksh 100,000 at 10% for 10 years: simple interest gives 200,000. Compound gives about…",
            listOf("Ksh 259,000", "Ksh 210,000", "Ksh 200,000", "Ksh 1,000,000"), 0,
            "100,000 × 1.1¹⁰ ≈ 259,374. The gap grows every year, which is why time is the strongest ingredient."),
        quiz("fb-monthly-rate", T, 3, "A lender charges 2% a month, compounding. What is that per year?",
            listOf("About 27%", "24%", "2%", "About 20%"), 0,
            "1.02¹² − 1 ≈ 26.8%. Always turn monthly or daily rates into yearly ones before you compare loans or returns."),
        quiz("fb-effective-rate", T, 3, "A 12% yearly rate compounded monthly really earns…",
            listOf("About 12.7% a year", "Exactly 12%", "About 13.5%", "About 11.4%"), 0,
            "(1 + 0.12/12)¹² − 1 ≈ 12.68%. The more often interest compounds, the higher the effective annual rate (EAR)."),
        quiz("fb-72-reverse", T, 3, "Using the rule of 72, what yearly return doubles your money in 6 years?",
            listOf("About 12%", "About 6%", "About 18%", "About 7.2%"), 0,
            "72 ÷ 6 = 12. It works both ways: years = 72 ÷ rate, and rate = 72 ÷ years."),
        concept("fb-72-limits", T, 3, "Where does the rule of 72 go wrong?",
            "It's tuned for about 6–10%. At 8% it's spot on (9 years). At 36% it says 2 years but the truth is 2.25. The exact answer is ln 2 ÷ ln(1 + r).",
            source = "Standard finance maths"),
        quiz("fb-real-return", T, 3, "A fund earns 11% a year. Inflation is 6.8%. Your real return is about…",
            listOf("About 4%", "About 11%", "About 17.8%", "About 6.8%"), 0,
            "Real ≈ (1.11 ÷ 1.068) − 1 ≈ 3.9%. Subtracting (11 − 6.8 = 4.2) is a fine shortcut. Only the real return makes you richer.",
            source = "KNBS CPI, Sep 2026", timeSensitive = true),
        quiz("fb-inflation-erosion", T, 3, "At 7% inflation for 10 years, Ksh 100,000 kept under the mattress buys what today's…",
            listOf("About Ksh 51,000 buys", "About Ksh 70,000 buys", "About Ksh 93,000 buys", "Ksh 100,000 buys"), 0,
            "100,000 ÷ 1.07¹⁰ ≈ 50,800. Cash that earns nothing quietly loses about half its power in a decade at 7%."),
        concept("fb-why-shilling-today", T, 3, "Why is a shilling today worth more than a shilling next year?",
            "Three reasons: you could earn a return on it meanwhile, inflation shrinks what it buys, and the future payment might not come. That's the time value of money."),
        quiz("fb-opportunity-cost", T, 3, "You skip a Ksh 30,000 phone upgrade and invest it at 10% a year. In 10 years it's about…",
            listOf("Ksh 78,000", "Ksh 33,000", "Ksh 60,000", "Ksh 300,000"), 0,
            "30,000 × 1.1¹⁰ ≈ 77,800. That's the opportunity cost: the best thing you give up. It doesn't mean never upgrade; it means know the real price."),
        concept("fb-opportunity-time", T, 3, "You spend 3 hours in town to save Ksh 200 on a shopping trip. What's the hidden cost?",
            "Your time. If you could earn Ksh 300 an hour hustling, those 3 hours cost Ksh 900 to save Ksh 200. Opportunity cost counts time and energy, not only money."),
        quiz("fb-start-early", T, 3, "Wanjiku saves Ksh 5,000/month from 25 to 35, then stops. Otieno saves 5,000/month from 35 to 60. At 10%, who has more at 60?",
            listOf("Wanjiku, about 12.3M vs 6.6M", "Otieno, he saved 2.5 times more", "About the same", "Otieno, about 9M vs 4M"), 0,
            "Wanjiku put in Ksh 600,000, Otieno Ksh 1.5 million. Her money just had 25 extra years to compound. Starting early beats saving more later.",
            source = "Compound interest, 10% a year"),
        quiz("fb-fees-compound", T, 3, "Ksh 300 a month lost to fees for 20 years. If invested at 10% instead, it would grow to about…",
            listOf("Ksh 228,000", "Ksh 72,000", "Ksh 100,000", "Ksh 600,000"), 0,
            "You'd put in 72,000; compounding makes it about 228,000. Small fees have a big compounded opportunity cost.",
            signals = setOf(Signal.HIGH_FEES)),
        quiz("fb-pay-debt-return", T, 3, "You have a loan at 30% a year and savings earning 10%. Paying off the loan is like earning…",
            listOf("A guaranteed 30% return", "A 10% return", "A 20% return with risk", "Nothing, debt is neutral"), 0,
            "Every shilling of 30% debt you clear saves 30% a year, risk-free. Few investments promise that. Keep a small emergency buffer, though.",
            signals = setOf(Signal.HAS_DEBT)),

        // ---- Level 4 · Shark ------------------------------------------------------------------
        concept("fb-balance-sheet", T, 4, "What goes on a personal balance sheet?",
            "Assets (cash, MMF, SACCO deposits, shares, land, a motorbike) on one side; liabilities (Fuliza, bank and SACCO loans, hire purchase) on the other. Assets minus liabilities = net worth, on one date.",
            tryThis = "List your accounts and loans in Accounts.", action = Action.ACCOUNTS),
        concept("fb-cash-flow", T, 4, "How is a cash-flow statement different from a balance sheet?",
            "A balance sheet is a photo: what you own and owe today. A cash-flow statement is a video: money in minus money out over a month. A surplus each month is what grows net worth."),
        quiz("fb-net-worth-calc", T, 4, "MMF 120k, SACCO deposits 200k, motorbike 90k. SACCO loan 150k, Fuliza 5k. Net worth?",
            listOf("Ksh 255,000", "Ksh 410,000", "Ksh 155,000", "Ksh 260,000"), 0,
            "Assets 410,000 − liabilities 155,000 = 255,000. Value the motorbike at what it would sell for today, not what you paid."),
        quiz("fb-savings-rate", T, 4, "Take-home Ksh 80,000. You spend Ksh 64,000. Your savings rate is…",
            listOf("20%", "16%", "25%", "80%"), 0,
            "Savings rate = (income − spending) ÷ income = 16,000 ÷ 80,000 = 20%. It's the single number that best predicts how fast you build wealth."),
        quiz("fb-savings-rate-years", T, 4, "Starting from zero, at a 5% real return, roughly how long to financial freedom saving 50% of pay?",
            listOf("About 17 years", "About 37 years", "About 52 years", "About 5 years"), 0,
            "Assuming you then live on 4% a year of the pot: about 52 years at a 10% savings rate, 37 at 20%, 17 at 50%. Saving more also means you need less.",
            source = "4% rule maths, 5% real return"),
        you("fb-you-savings-rate", T, 4, "Your savings rate is about {savings_rate}. What would add 5 points to it?",
            "A raise you don't spend, one fixed cost cut, or a fee you stop paying. Each point of savings rate both grows your pot and lowers what you need to live on.",
            tryThis = "Pick one fixed cost to cut or one auto-save to raise.", action = Action.BUDGETS),
        quiz("fb-dti", T, 4, "Loan repayments of Ksh 18,000 a month on a gross income of Ksh 60,000. Debt-to-income ratio?",
            listOf("30%", "18%", "42%", "3.3%"), 0,
            "18,000 ÷ 60,000 = 30%. Lenders use DTI to judge if you can carry more debt; the higher it is, the less room you have when life happens.",
            signals = setOf(Signal.HAS_DEBT)),
        quiz("fb-two-thirds", T, 4, "Kenya's Employment Act caps total payslip deductions at what share of wages?",
            listOf("Two-thirds", "One-half", "One-third", "There is no cap"), 0,
            "Section 19(3) of the Employment Act 2007 caps deductions at two-thirds. New levies have pushed many payslips close to it, which squeezes check-off loans.",
            source = "Employment Act 2007, s.19(3)", timeSensitive = true),
        concept("fb-liquidity", T, 4, "Why might Ksh 300,000 in SACCO deposits not count as your emergency fund?",
            "Liquidity: how fast you can get cash without losing value. SACCO deposits usually come back only when you leave, after notice, though they back loans. Emergencies need money you can reach in days.",
            source = "SASRA"),
        concept("fb-liquidity-ratio", T, 4, "What is the liquidity (emergency) ratio and what does it tell you?",
            "Liquid assets ÷ monthly essential spending. Ksh 90,000 liquid against 30,000 a month = 3 months. It's how long you survive a lost income without borrowing.",
            signals = setOf(Signal.NO_EMERGENCY_FUND)),
        quiz("fb-car-asset", T, 4, "You bought a car for Ksh 1.2M with a loan of Ksh 900,000. Why can it hurt net worth over time?",
            listOf("It loses value while the loan costs interest", "Cars always gain value", "Loans don't affect net worth", "Insurance counts as an asset"), 0,
            "A car is an asset that depreciates. If it loses value faster than you pay down the loan, net worth falls even as you pay. Value it at resale price."),
        concept("fb-solvency", T, 4, "What does the solvency ratio (net worth ÷ total assets) show?",
            "How much of what you own is truly yours. 0.8 means 80% is paid for; near zero or negative means debt owns most of it and one bad shock could tip you under."),
        concept("fb-automation", T, 4, "What does a good money system look like?",
            "Decisions made once, then automatic: on payday, savings move first (standing order to an MMF or SACCO), bills get their own pot, and what's left is guilt-free spending.",
            tryThis = "Turn on Auto-sort so incoming money lands in envelopes.", action = Action.AUTOSORT, signals = setOf(Signal.MONEY_IN_RECENT)),
        concept("fb-runway", T, 4, "Before you quit a job to run a business full time, what is your \"runway\"?",
            "Liquid savings ÷ monthly personal spending = months you can live with zero income. Ksh 360,000 ÷ 40,000 = 9 months. Most founders need longer than they plan."),

        // ---- Level 5 · Legend -----------------------------------------------------------------
        quiz("fb-pv", T, 5, "At a 10% discount rate, what is Ksh 100,000 received in 5 years worth today?",
            listOf("About Ksh 62,000", "About Ksh 50,000", "About Ksh 90,000", "Ksh 100,000"), 0,
            "PV = FV ÷ (1 + r)ⁿ = 100,000 ÷ 1.1⁵ ≈ 62,092. Discounting is compounding run backwards.",
            source = "Time value of money"),
        quiz("fb-fv-annuity", T, 5, "You save Ksh 10,000 at the end of each year for 10 years at 10%. Future value?",
            listOf("About Ksh 159,000", "Ksh 100,000", "About Ksh 259,000", "About Ksh 110,000"), 0,
            "FV of an annuity = P × ((1 + r)ⁿ − 1) ÷ r = 10,000 × 15.94 ≈ 159,374. Pay at the start of each year (an annuity due) and it's ×1.1 ≈ 175,300."),
        quiz("fb-pv-annuity", T, 5, "At 10%, which is worth more today: Ksh 1,000,000 now, or Ksh 150,000 a year for 10 years?",
            listOf("Ksh 1,000,000 now", "Ksh 150,000 a year", "They're equal", "Can't compare them"), 0,
            "PV of the stream = 150,000 × (1 − 1.1⁻¹⁰) ÷ 0.1 ≈ 921,700. The 1.5M total looks bigger, but money later is worth less."),
        concept("fb-perpetuity", T, 5, "What is a perpetuity, and how does it link to your freedom number?",
            "A payment forever. Its value today = payment ÷ rate. Ksh 60,000 a year forever at 6% = Ksh 1,000,000. Your freedom number is the pot whose real return pays your costs forever.",
            source = "Time value of money"),
        concept("fb-continuous", T, 5, "What happens if interest compounds continuously?",
            "Growth becomes e^(rt). Ksh 100,000 at 10% for 10 years → 100,000 × e ≈ 271,828, versus 259,374 compounded yearly. The limit of compounding ever more often."),
        concept("fb-life-cycle", T, 5, "What does the life-cycle hypothesis (Modigliani & Brumberg, 1954) predict?",
            "People smooth spending over life: borrow when young, save hard in peak earning years, run down savings in old age. Wealth peaks around retirement. Modigliani won the 1985 Nobel partly for it.",
            source = "Modigliani & Brumberg, 1954"),
        quiz("fb-permanent-income", T, 5, "Friedman's permanent income hypothesis (1957) says a one-off windfall should mostly be…",
            listOf("Saved, with spending rising only a little", "Spent within the month", "Used to quit your job", "Ignored entirely"), 0,
            "Spending follows long-run expected income, not this month's. A bonus barely changes permanent income, so theory says save most of it.",
            source = "Friedman, 1957"),
        concept("fb-excess-sensitivity", T, 5, "Do real households follow permanent-income theory with windfalls?",
            "Often not. US households spent about 20–40% of 2001 tax rebates on non-durables within 3 months, and about two-thirds within 6 months. Cash on hand drives spending more than theory says.",
            source = "Johnson, Parker & Souleles, 2006"),
        concept("fb-campbell", T, 5, "What did John Campbell's \"Household Finance\" (2006) find about ordinary people's money mistakes?",
            "Many households don't invest at all, hold too few assets, or fail to refinance costly loans. These mistakes are most common among poorer, less-educated households, so mistakes widen inequality.",
            source = "Campbell, 2006, J. of Finance"),
        quiz("fb-big-three", T, 5, "Lusardi & Mitchell's \"Big Three\" financial literacy questions test compound interest, inflation and…",
            listOf("Risk diversification", "Tax filing", "Mortgage rules", "Budgeting apps"), 0,
            "They're used in surveys worldwide. Even in the US, well under half of adults answer all three correctly.",
            source = "Lusardi & Mitchell, 2011"),
        quiz("fb-big-three-q", T, 5, "Big Three question: Ksh 100 at 2% a year for 5 years. Without touching it you'll have…",
            listOf("More than Ksh 102", "Exactly Ksh 102", "Less than Ksh 102", "Don't know"), 0,
            "Each year earns 2 on 100+, so more than 102 (about 110.4). Many adults get even this one wrong, and \"don't know\" is a common answer.",
            source = "Lusardi & Mitchell, 2011"),
        quiz("fb-big-three-div", T, 5, "True or false: buying one company's shares is usually safer than a fund holding many shares.",
            listOf("False", "True", "True for NSE blue chips", "Only true in a bull market"), 0,
            "Diversification spreads risk: one firm can collapse, a broad fund rarely does. This is the Big Three question most people get wrong.",
            source = "Lusardi & Mitchell, 2011"),
        quiz("fb-fernandes", T, 5, "A 2014 meta-analysis of 201 studies found financial education explained what share of later money behaviour?",
            listOf("About 0.1%", "About 10%", "About 30%", "About 50%"), 0,
            "Fernandes, Lynch & Netemeyer found tiny effects that faded to negligible about 20 months after even long courses. They suggested \"just-in-time\" learning tied to real decisions.",
            source = "Fernandes, Lynch & Netemeyer, 2014"),
        concept("fb-fernandes-debate", T, 5, "Is financial education useless, then?",
            "No. A larger 2022 meta-analysis of 76 randomized trials (Kaiser, Lusardi, Menkhoff & Urban) found effects at least three times bigger. Lesson: learning works best paired with habits and timely nudges.",
            source = "Kaiser et al., 2022, J. Financial Economics"),
        concept("fb-mpesa-poverty", T, 5, "What did Suri & Jack (2016, Science) estimate M-Pesa did for Kenya?",
            "Lifted about 194,000 households, roughly 2%, out of poverty, mostly via saving and resilience, with bigger effects for female-headed homes. Critics argue the estimate is overstated.",
            source = "Suri & Jack, 2016"),
    )
}
